CREATE TABLE public.role (
  role_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  role_name TEXT NOT NULL UNIQUE
);
CREATE TABLE public.permission (
  permission_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  permission_name TEXT NOT NULL UNIQUE
);
CREATE TABLE public.role_permission (
  role_id INTEGER NOT NULL REFERENCES public.role(role_id),
  permission_id INTEGER NOT NULL REFERENCES public.permission(permission_id),
  PRIMARY KEY (role_id, permission_id)
);
INSERT INTO public.role (role_name) VALUES
  ('Admin'), ('Conservation Officer'), ('Botanist'), ('Visitor');
INSERT INTO public.permission (permission_name) VALUES
  ('manage_users'), ('manage_species'), ('register_plants'),
  ('record_observations'), ('verify_observations'), ('view_plants'),
  ('manage_sensors'), ('view_alerts'), ('manage_qr_codes');
INSERT INTO public.role_permission (role_id, permission_id)
SELECT r.role_id, p.permission_id
  FROM public.role AS r CROSS JOIN public.permission AS p
 WHERE (r.role_name = 'Admin')
    OR (r.role_name = 'Conservation Officer' AND p.permission_name <> 'manage_users')
    OR (r.role_name = 'Botanist' AND p.permission_name IN ('manage_species','register_plants','record_observations','view_plants'))
    OR (r.role_name = 'Visitor' AND p.permission_name = 'view_plants');
